import assert from "node:assert/strict"
import { readFileSync, writeFileSync } from "node:fs"

const locales = JSON.parse(
  readFileSync(new URL("./strings.json", import.meta.url), "utf8"),
)
const output = new URL("./strings.iss", import.meta.url)
const keys = Object.keys(locales.en.text).sort()
const lines = [
  "; Generated by generate-strings.mjs; edit strings.json.",
  "[CustomMessages]",
]

for (const [locale, { text }] of Object.entries(locales)) {
  assert.deepEqual(Object.keys(text).sort(), keys)
  for (const [key, value] of Object.entries(text)) {
    assert.equal(typeof value, "string")
    assert.ok(value.length > 0 && !/[\r\n\u2014%]/u.test(value))
    lines.push(`${locale.replaceAll("-", "")}.${key}=${value}`)
  }
}
const rendered = lines.join("\n") + "\n"
if (process.argv.includes("--check")) {
  assert.equal(readFileSync(output, "utf8").replaceAll("\r\n", "\n"), rendered)
} else {
  writeFileSync(output, rendered)
}
